mapper.select:
SELECT 
FROM dataset_versions
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}
  AND archived_at IS NULL
  AND deleted_at IS NULL

SELECT 
FROM dataset_versions
WHERE dataset_id = #{datasetId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}
ORDER BY version_no DESC

SELECT COALESCE(MAX(version_no), 0) + 1
FROM dataset_versions
WHERE dataset_id = #{datasetId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}

SELECT v.*
FROM dataset_versions v
JOIN datasets d ON d.current_version_id = v.id

    v.owner_id = #{ownerId}
    AND d.deleted_at IS NULL

        AND v.status = #{status}


        AND (LOWER(v.name) LIKE #{keywordPattern} OR LOWER(v.original_filename) LIKE #{keywordPattern})


        AND LOWER(v.original_filename) LIKE #{formatPattern}



            AND v.table_count > 0
            AND v.table_count = 0



ORDER BY v.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM dataset_versions v
JOIN datasets d ON d.current_version_id = v.id

    v.owner_id = #{ownerId}
    AND d.deleted_at IS NULL

        AND v.status = #{status}


        AND (LOWER(v.name) LIKE #{keywordPattern} OR LOWER(v.original_filename) LIKE #{keywordPattern})


        AND LOWER(v.original_filename) LIKE #{formatPattern}



            AND v.table_count > 0
            AND v.table_count = 0

SELECT name
FROM dataset_versions
WHERE name LIKE #{pattern}
  AND owner_id = #{ownerId}

