mapper.update:
UPDATE dataset_versions
SET archived_at = #{archivedAt,typeHandler=org.apache.ibatis.type.InstantTypeHandler},
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.InstantTypeHandler}
WHERE dataset_id = #{datasetId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}
  AND archived_at IS NULL

